 const map={'4-3-3':{공격:3,중원:1,수비:-.5},'4-2-3-1':{공격:1.5,중원:2.5,수비:1},'4-4-2':{공격:2,중원:0,수비:1},'3-4-2-1':{공격:2.5,중원:1.5,수비:-1.5},'3-5-2':{공격:1,중원:4,수비:-1},'4-1-4-1':{공격:0,중원:3.5,수비:2}};
